update product
name = #{name}, category_id = #{categoryId}, price = #{price}, image = #{image}, description = #{description}, status = #{status}, stock = #{stock}, low_stock_warning = #{lowStockWarning}, sales = #{sales}, update_time = #{updateTime}, update_user = #{updateUser}
